@startuml

class CarPark {}

class Barrier {
  + raise()
}

class CardReader {
  + verifyCardNumber()
}

class Signal {}

class Sign {
  + displayFull()
  + switchOff()
}

class Card {
  + number: string
}

class StaffCard extends Card {
  + name: string
  + department: string
  + staffNumber: string
}

class GuestCard extends Card {
  + number: string
  + currentDate: date
}

class Employee {
  + name: string
  + department: string
  + staffNumber: string
}

CarPark "1" *-- "*" Barrier
CarPark "1" *-- "1" CardReader
CarPark "1" -- "1" Sign
CardReader ..> Signal : triggers
Barrier ..> Signal : triggers
Employee "1" -- "1" StaffCard : wears

@enduml

